values
('bmlt-integrateddiagnosis1-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"Microcytic hypochromic anemia with low ferritin most strongly suggests:","translation":"","options":["Iron deficiency anemia","Vitamin B12 deficiency","Aplastic anemia","Hemolytic anemia"],"correctIndex":0,"explanation":"Low ferritin indicates depleted iron stores, commonly causing microcytic hypochromic anemia.","explanationNe":"Ferritin कम हुनु iron store घटेको संकेत हो; iron deficiency मा microcytic hypochromic anemia हुन्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"Macrocytosis with hypersegmented neutrophils is typical of:","translation":"","options":["Megaloblastic anemia","Iron deficiency","Thalassemia trait","Acute blood loss"],"correctIndex":0,"explanation":"B12 or folate deficiency causes impaired DNA synthesis and megaloblastic changes.","explanationNe":"B12 वा folate कमीले DNA synthesis बिगारी megaloblastic परिवर्तन गर्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"A prolonged PT with normal aPTT may indicate an early deficiency of:","translation":"","options":["Factor VII","Factor VIII","Factor IX","Factor XII"],"correctIndex":0,"explanation":"Factor VII is in the extrinsic pathway and affects PT early.","explanationNe":"Factor VII extrinsic pathway मा हुन्छ र PT पहिले बढ्न सक्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"A markedly prolonged aPTT with normal PT is classically associated with deficiency of:","translation":"","options":["Factor VIII","Factor VII","Factor V","Factor X"],"correctIndex":0,"explanation":"Factor VIII deficiency affects the intrinsic pathway and prolongs aPTT.","explanationNe":"Factor VIII कमीले intrinsic pathway प्रभावित गरी aPTT बढाउँछ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"Neutrophilia with toxic granulation commonly supports:","translation":"","options":["Acute bacterial infection/inflammation","Viral infection only","Iron deficiency alone","Severe hypothyroidism"],"correctIndex":0,"explanation":"Toxic changes may occur with significant bacterial infection or inflammation.","explanationNe":"Toxic granulation गम्भीर bacterial infection वा inflammation मा देखिन सक्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"A low platelet count with clumping on EDTA smear may be due to:","translation":"","options":["Pseudothrombocytopenia","True severe thrombocytopenia always","Polycythemia","Hemophilia"],"correctIndex":0,"explanation":"EDTA-dependent platelet clumping can falsely lower automated platelet count.","explanationNe":"EDTA मा platelet clump हुँदा automated count झूटो कम आउन सक्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"Elevated reticulocyte count in anemia suggests:","translation":"","options":["Marrow response to blood loss or hemolysis","Complete marrow failure in all cases","Iron stores are always normal","No red cell production"],"correctIndex":0,"explanation":"Reticulocytosis indicates increased red cell production after loss or destruction.","explanationNe":"Reticulocyte बढ्नु रक्तस्राव वा hemolysis पछि marrow response हुन सक्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"High unconjugated bilirubin, raised LDH and low haptoglobin suggest:","translation":"","options":["Hemolysis","Obstructive jaundice only","Renal stone","Iron overload only"],"correctIndex":0,"explanation":"These findings are typical biochemical markers of red cell destruction.","explanationNe":"यी finding हरू red cell destruction अर्थात् hemolysis सँग मेल खान्छन्।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"A patient has fasting plasma glucose 130 mg/dL on repeat testing. This is in the diabetic range by:","translation":"","options":["Fasting plasma glucose criterion","Random glucose criterion only","Urine glucose alone","Hb concentration"],"correctIndex":0,"explanation":"Fasting plasma glucose ≥126 mg/dL on confirmatory testing meets the diagnostic threshold.","explanationNe":"पुष्टि भएको fasting glucose ≥126 mg/dL diabetes diagnostic range हो।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',10,'{"question":"HbA1c reflects average glycemia over approximately:","translation":"","options":["2–3 months","24 hours","One week","One year"],"correctIndex":0,"explanation":"HbA1c reflects glycation over the red cell lifespan, roughly 2–3 months.","explanationNe":"HbA1c ले करिब 2–3 महिनाको औसत glucose दर्शाउँछ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"A raised serum creatinine most directly indicates reduced:","translation":"","options":["Glomerular filtration","Liver bile production","Platelet function","Thyroid hormone synthesis"],"correctIndex":0,"explanation":"Creatinine rises when renal filtration is reduced, though interpretation has caveats.","explanationNe":"Renal filtration घट्दा creatinine बढ्न सक्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"An elevated urea-to-creatinine ratio may occur in:","translation":"","options":["Prerenal volume depletion","All cases of nephrotic syndrome","Hypoglycemia","Thrombocytopenia"],"correctIndex":0,"explanation":"Reduced renal perfusion can increase urea reabsorption disproportionately.","explanationNe":"Prerenal अवस्था हुँदा urea reabsorption बढी भएर ratio बढ्न सक्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"ALT is generally more liver-specific than:","translation":"","options":["AST","Albumin","Bilirubin","ALP"],"correctIndex":0,"explanation":"ALT is more concentrated in hepatocytes than AST, though neither is perfectly specific.","explanationNe":"ALT hepatocyte मा बढी केन्द्रित भएकाले AST भन्दा liver-specific हुन्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',14,'{"question":"Raised ALP with raised GGT supports a:","translation":"","options":["Hepatobiliary source of ALP","Bone source only","Hemolytic anemia","Pancreatic insufficiency"],"correctIndex":0,"explanation":"GGT elevation alongside ALP supports a hepatobiliary origin.","explanationNe":"ALP सँग GGT बढ्दा hepatobiliary स्रोतको सम्भावना हुन्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',15,'{"question":"Low albumin with prolonged PT in chronic liver disease suggests:","translation":"","options":["Reduced hepatic synthetic function","Increased platelet production","Improved liver function","Acute dehydration only"],"correctIndex":0,"explanation":"Albumin and clotting factors are synthesized by the liver.","explanationNe":"Albumin र clotting factor liver मा बन्ने भएकाले कमीले synthetic function घटेको देखाउँछ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',16,'{"question":"A serum sample that is visibly hemolyzed may falsely increase:","translation":"","options":["Potassium","Sodium always","Chloride always","Glucose always"],"correctIndex":0,"explanation":"Red cell lysis releases intracellular potassium into serum.","explanationNe":"Hemolysis हुँदा red cell बाट potassium serum मा निस्कन्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',17,'{"question":"A blood culture should ideally be collected:","translation":"","options":["Before antimicrobial therapy, when feasible","Only after several antibiotic doses","From an opened IV fluid bottle","After discarding all specimen"],"correctIndex":0,"explanation":"Collecting cultures before antibiotics improves the chance of organism recovery.","explanationNe":"सम्भव भए antibiotic सुरु गर्नुअघि culture लिँदा organism भेटिने सम्भावना बढ्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-018','BMLT','BMLT NHPC Licensing','mcq','free',18,'{"question":"A positive nitrite urine dipstick suggests:","translation":"","options":["Presence of nitrate-reducing bacteria","All urinary pathogens","No bacterial infection","Renal failure definitely"],"correctIndex":0,"explanation":"Some bacteria convert urinary nitrate to nitrite; a negative result does not exclude UTI.","explanationNe":"केही bacteria ले nitrate लाई nitrite बनाउँछन्; negative भए पनि UTI नकारिँदैन।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-019','BMLT','BMLT NHPC Licensing','mcq','free',19,'{"question":"Urine microscopy showing red cell casts strongly suggests:","translation":"","options":["Glomerular renal bleeding","Lower urinary tract stone only","Normal urine","Contamination by skin cells"],"correctIndex":0,"explanation":"RBC casts form in renal tubules and indicate intrarenal, often glomerular, bleeding.","explanationNe":"RBC cast kidney tubule मा बन्ने भएकाले renal, प्रायः glomerular, bleeding जनाउँछ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',20,'{"question":"CSF with neutrophilic pleocytosis, low glucose and high protein suggests:","translation":"","options":["Bacterial meningitis","Typical viral meningitis","Normal CSF","Multiple myeloma"],"correctIndex":0,"explanation":"This CSF pattern is characteristic of bacterial meningitis, interpreted clinically.","explanationNe":"Neutrophil बढ्नु, glucose घट्नु र protein बढ्नु bacterial meningitis मा देखिन सक्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-021','BMLT','BMLT NHPC Licensing','mcq','free',21,'{"question":"A high ESR is a nonspecific marker of:","translation":"","options":["Inflammation","Specific bacterial species","Blood group","Exact viral load"],"correctIndex":0,"explanation":"ESR can rise in many inflammatory, infectious and other conditions.","explanationNe":"ESR धेरै inflammatory वा अन्य अवस्थाहरूमा बढ्न सक्छ; specific test होइन।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',22,'{"question":"A markedly elevated D-dimer is best interpreted as:","translation":"","options":["Evidence of fibrin turnover, not specific for thrombosis","Proof of pulmonary embolism","Proof of normal coagulation","A platelet count"],"correctIndex":0,"explanation":"D-dimer is sensitive but nonspecific and must be interpreted with clinical probability.","explanationNe":"D-dimer fibrin breakdown दर्शाउँछ तर thrombosis को specific proof होइन।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-023','BMLT','BMLT NHPC Licensing','mcq','free',23,'{"question":"A blood group forward typing and reverse typing discrepancy should be:","translation":"","options":["Investigated and resolved before final ABO assignment","Ignored if forward typing is clear","Reported as AB automatically","Solved by changing the patient''s name"],"correctIndex":0,"explanation":"ABO discrepancies require investigation and appropriate repeat testing.","explanationNe":"ABO discrepancy जाँचेर समाधान गरेपछि मात्र final group report गर्नुपर्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-024','BMLT','BMLT NHPC Licensing','mcq','free',24,'{"question":"A crossmatch is performed primarily to assess:","translation":"","options":["Compatibility between donor red cells and recipient serum/plasma","Serum glucose","Urine concentration","Bacterial motility"],"correctIndex":0,"explanation":"Crossmatching helps detect clinically significant incompatibility before transfusion.","explanationNe":"Crossmatch ले transfusion अघि donor र recipient बीच incompatibility खोज्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mcq-025','BMLT','BMLT NHPC Licensing','mcq','free',25,'{"question":"A laboratory result is inconsistent with the patient''s condition. The best first step is to:","translation":"","options":["Check specimen identity, quality, QC and analytical flags","Immediately change the result","Ignore the clinician","Release without review"],"correctIndex":0,"explanation":"A systematic verification process helps identify preanalytical or analytical error.","explanationNe":"Result नमिले sample identity, quality, QC र analyzer flag जाँच्नुपर्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
