('bmlt-integrateddiagnosis1-mock-002','BMLT','BMLT NHPC Licensing','mock','free',2,'{"question":"A patient with jaundice has high indirect bilirubin, high LDH and low haptoglobin. Which process is likely?","translation":"","options":["Hemolysis","Bile duct obstruction","Acute pancreatitis","Iron deficiency"],"correctIndex":0,"explanation":"The combination supports red cell destruction.","explanationNe":"यी परिणामले red cell destruction अर्थात् hemolysis जनाउँछन्।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
