('bmlt-integrateddiagnosis1-mock-004','BMLT','BMLT NHPC Licensing','mock','free',4,'{"question":"A platelet count is 45,000/µL but smear shows platelet clumps. What should be done?","translation":"","options":["Repeat count using an appropriate alternative anticoagulant/sample method","Diagnose immune thrombocytopenia immediately","Report without comment","Perform only PT"],"correctIndex":0,"explanation":"Clumping can cause a spurious low count; verify with smear and repeat method.","explanationNe":"Platelet clump ले झूटो कम count दिन सक्छ; smear र repeat method बाट पुष्टि गर्नुपर्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mock-005','BMLT','BMLT NHPC Licensing','mock','free',5,'{"question":"A patient has polyuria and fasting glucose 145 mg/dL on confirmatory testing. Interpretation?","translation":"","options":["Diabetes mellitus range","Normal fasting glucose","Hypoglycemia","Only impaired fasting glucose"],"correctIndex":0,"explanation":"A confirmed fasting glucose ≥126 mg/dL meets the diabetes threshold.","explanationNe":"पुष्टि भएको fasting glucose ≥126 mg/dL diabetes range हो।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mock-006','BMLT','BMLT NHPC Licensing','mock','free',6,'{"question":"Creatinine is elevated and eGFR is reduced. This most directly indicates:","translation":"","options":["Reduced kidney filtration","Increased liver synthesis","Increased platelet activity","Low thyroid antibody"],"correctIndex":0,"explanation":"eGFR estimates filtration and decreases with impaired renal function.","explanationNe":"eGFR घट्नु kidney filtration कम भएको संकेत हो।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mock-007','BMLT','BMLT NHPC Licensing','mock','free',7,'{"question":"AST and ALT are markedly elevated in a patient with acute hepatitis. These enzymes indicate:","translation":"","options":["Hepatocellular injury","Kidney stone","Bone marrow failure","Coagulation factor deficiency"],"correctIndex":0,"explanation":"Transaminases rise with hepatocyte injury.","explanationNe":"Hepatocyte injury हुँदा AST र ALT बढ्न सक्छन्।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mock-008','BMLT','BMLT NHPC Licensing','mock','free',8,'{"question":"ALP is high, GGT high, and bilirubin elevated. This pattern suggests:","translation":"","options":["Cholestatic/hepatobiliary disease","Isolated bone disease only","Iron deficiency","Hemolysis only"],"correctIndex":0,"explanation":"The enzyme pattern supports a hepatobiliary cholestatic process.","explanationNe":"ALP, GGT र bilirubin बढ्नु hepatobiliary cholestasis सँग मेल खान्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mock-009','BMLT','BMLT NHPC Licensing','mock','free',9,'{"question":"Urine dipstick is nitrite positive and leukocyte esterase positive in a symptomatic patient. Most likely?","translation":"","options":["Urinary tract infection","Diabetes insipidus","Nephrotic syndrome definitely","Normal urine"],"correctIndex":0,"explanation":"These findings support bacteriuria and pyuria; culture may be indicated.","explanationNe":"यी finding ले bacteriuria र pyuria समर्थन गर्छन्; आवश्यक परे culture गरिन्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mock-010','BMLT','BMLT NHPC Licensing','mock','free',10,'{"question":"CSF has high neutrophils, low glucose and high protein. What should be urgently considered?","translation":"","options":["Bacterial meningitis","Migraine only","Normal CSF","Simple dehydration"],"correctIndex":0,"explanation":"This is a concerning pattern for bacterial meningitis requiring urgent clinical action.","explanationNe":"यो bacterial meningitis को चिन्ताजनक pattern हो र तुरुन्त clinical action चाहिन्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mock-011','BMLT','BMLT NHPC Licensing','mock','free',11,'{"question":"A blood culture was collected after antibiotics and remains negative. Does this exclude infection?","translation":"","options":["No; antibiotics can reduce culture yield","Yes, always","It proves viral infection","It proves contamination"],"correctIndex":0,"explanation":"Prior antibiotics may suppress organism growth and reduce sensitivity.","explanationNe":"पहिले antibiotic लिँदा organism growth घटेर culture sensitivity कम हुन सक्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mock-012','BMLT','BMLT NHPC Licensing','mock','free',12,'{"question":"D-dimer is elevated in an older hospitalized patient. What is the correct interpretation?","translation":"","options":["Nonspecific; assess clinical probability and further testing","Definite pulmonary embolism","Definite DVT","No clotting process possible"],"correctIndex":0,"explanation":"D-dimer elevation occurs in many conditions and is not diagnostic alone.","explanationNe":"D-dimer धेरै अवस्थामा बढ्छ; एक्लै thrombosis diagnose गर्दैन।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mock-013','BMLT','BMLT NHPC Licensing','mock','free',13,'{"question":"A transfusion recipient develops fever and chills shortly after blood starts. First action?","translation":"","options":["Stop transfusion and follow transfusion reaction protocol","Increase transfusion rate","Discard the patient''s identification","Give another unit immediately"],"correctIndex":0,"explanation":"Suspected acute reaction requires stopping transfusion and urgent assessment.","explanationNe":"Acute reaction शंका हुँदा transfusion रोक्दै protocol अनुसार तुरुन्त जाँच गर्नुपर्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mock-014','BMLT','BMLT NHPC Licensing','mock','free',14,'{"question":"ABO forward and reverse typing disagree. What is the safest action?","translation":"","options":["Hold result and investigate discrepancy","Assign group from one test only","Label as O without testing","Issue incompatible blood"],"correctIndex":0,"explanation":"Resolve ABO discrepancy before final reporting or transfusion selection.","explanationNe":"ABO discrepancy समाधान नगरी final group वा blood issue गर्नु हुँदैन।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mock-015','BMLT','BMLT NHPC Licensing','mock','free',15,'{"question":"A QC control result is outside acceptable limits. Patient testing should:","translation":"","options":["Be held until the problem is investigated and QC is acceptable","Continue and report all results","Be corrected by guessing","Ignore the control"],"correctIndex":0,"explanation":"Out-of-range QC signals possible analytical error.","explanationNe":"QC limit बाहिर भए समस्या समाधान र QC acceptable नभएसम्म patient result रोक्नुपर्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mock-016','BMLT','BMLT NHPC Licensing','mock','free',16,'{"question":"A sample tube is unlabeled but accompanied by a request form. The lab should:","translation":"","options":["Reject or resolve according to specimen identification policy","Label it from memory","Test it and guess later","Combine it with another sample"],"correctIndex":0,"explanation":"Unlabeled specimens create serious patient-identification risk.","explanationNe":"Unlabeled sample ले patient identification जोखिम निम्त्याउँछ; policy अनुसार reject/resolve गर्नुपर्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mock-017','BMLT','BMLT NHPC Licensing','mock','free',17,'{"question":"A hemolyzed serum sample has potassium 6.8 mmol/L but clinical findings do not fit. Best response?","translation":"","options":["Assess hemolysis and recollect promptly if indicated","Report as definitely true without comment","Dilute until normal","Change to 4.0"],"correctIndex":0,"explanation":"Hemolysis can falsely elevate potassium; verify urgently with proper specimen.","explanationNe":"Hemolysis ले potassium झूटो बढाउन सक्छ; उचित sample बाट छिटो पुष्टि गर्नुपर्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
