('bmlt-integrateddiagnosis1-mock-019','BMLT','BMLT NHPC Licensing','mock','free',19,'{"question":"A stool sample is submitted for ova and parasite examination. Proper collection should avoid:","translation":"","options":["Mixing with urine or water","Clean leak-proof container","Prompt transport as instructed","Correct patient labeling"],"correctIndex":0,"explanation":"Urine or water contamination can compromise stool microscopy.","explanationNe":"Urine वा पानी मिसिँदा stool microscopy बिग्रन सक्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mock-020','BMLT','BMLT NHPC Licensing','mock','free',20,'{"question":"A patient has severe anemia and low reticulocyte count. This suggests:","translation":"","options":["Inadequate marrow response or reduced production","Strong compensatory response always","Only acute hemolysis","Normal erythropoiesis"],"correctIndex":0,"explanation":"Low reticulocytes in anemia indicate insufficient red cell production.","explanationNe":"Anemia हुँदा reticulocyte कम हुनु red cell production अपर्याप्त भएको संकेत हो।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mock-021','BMLT','BMLT NHPC Licensing','mock','free',21,'{"question":"A smear shows blasts in peripheral blood. What is the appropriate next step?","translation":"","options":["Urgent review and referral for hematology evaluation","Report as normal","Ignore if Hb is normal","Only perform urine microscopy"],"correctIndex":0,"explanation":"Blasts may indicate serious marrow disease and require prompt expert review.","explanationNe":"Peripheral blood मा blast देखिए गम्भीर marrow रोग हुन सक्छ; तुरुन्त hematology review चाहिन्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
('bmlt-integrateddiagnosis1-mock-022','BMLT','BMLT NHPC Licensing','mock','free',22,'{"question":"A laboratory notices repeated specimen rejection due to hemolysis. Best quality improvement approach?","translation":"","options":["Analyze causes, staff technique and collection process; monitor indicators","Blame one patient","Stop measuring potassium","Hide rejection records"],"correctIndex":0,"explanation":"A quality improvement cycle targets root causes and tracks rejection rates.","explanationNe":"Quality improvement ले root cause पत्ता लगाई rejection rate monitor गर्छ।","topic":"Integrated Clinical Laboratory Diagnosis"}'::jsonb,true),
